function alloc(income, weights){
  return weights.map(function(w){ return income*w; });
}
function alloc502010(income){ return {needs:income*0.5, wants:income*0.3, savings:income*0.2}; }
var EXPORTS={alloc:alloc, alloc502010:alloc502010};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BudgetForgePure = EXPORTS; }
